def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a state machine approach.
    This technique maintains a state that determines which part of the JSON structure is being parsed.
    Handles strings (with escapes), numbers, booleans, null, arrays, and objects.
    """

    class State:
        EXPECT_VALUE = 0
        STRING = 1
        NUMBER = 2
        BOOL = 3
        NULL = 4
        ARRAY = 5
        DICT = 6

    pos = 0
    length = len(s)
    current_state = State.EXPECT_VALUE
    stack = []
    current_obj = None

    def consume_whitespace():
        nonlocal pos
        while pos < length and s[pos].isspace():
            pos += 1

    def parse_value():
        nonlocal current_state, current_obj
        consume_whitespace()

        if pos >= length:
            raise ValueError("Unexpected end of JSON string")

        char = s[pos]

        if char == '"':
            current_state = State.STRING
            return parse_string()
        elif char.isdigit() or (char == '-' and (pos + 1 < length and s[pos + 1].isdigit())):
            current_state = State.NUMBER
            return parse_number()
        elif s.startswith('true', pos):
            current_state = State.BOOL
            pos += 4
            return True
        elif s.startswith('false', pos):
            current_state = State.BOOL
            pos += 5
            return False
        elif s.startswith('null', pos):
            current_state = State.NULL
            pos += 4
            return None
        elif char == '[':
            current_state = State.ARRAY
            pos += 1
            return parse_array()
        elif char == '{':
            current_state = State.DICT
            pos += 1
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: '{char}'")

    def parse_string():
        nonlocal pos
        start = pos + 1
        pos += 1  # Skip opening quote
        while pos < length:
            if s[pos] == '"':
                result = s[start:pos]
                pos += 1  # Skip closing quote
                return result
            elif s[pos] == '\\':
                pos += 1  # Skip escape character
            pos += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal pos
        start = pos
        if s[pos] == '-':
            pos += 1
        while pos < length and (s[pos].isdigit() or s[pos] == '.'):
            pos += 1
        num_str = s[start:pos]
        return float(num_str) if '.' in num_str else int(num_str)

    def parse_array():
        nonlocal pos
        array = []
        while pos < length:
            consume_whitespace()
            if pos < length and s[pos] == ']':
                pos += 1  # Skip closing bracket
                return array
            array.append(parse_value())
            consume_whitespace()
            if pos < length and s[pos] == ',':
                pos += 1  # Skip comma
        raise ValueError("Expected ']' in array")

    def parse_object():
        nonlocal pos
        obj = {}
        while pos < length:
            consume_whitespace()
            if pos < length and s[pos] == '}':
                pos += 1  # Skip closing brace
                return obj
            key = parse_string()
            consume_whitespace()
            if s[pos] != ':':
                raise ValueError("Expected ':' after key in object")
            pos += 1  # Skip colon
            value = parse_value()
            obj[key] = value
            consume_whitespace()
            if pos < length and s[pos] == ',':
                pos += 1  # Skip comma
        raise ValueError("Expected '}' in object")

    return parse_value()

