def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a finite-state machine approach.
    Handles strings with escapes, numbers, booleans, null, arrays, and objects.
    """

    pos = 0
    length = len(s)

    def next_token():
        nonlocal pos
        while pos < length and s[pos].isspace():
            pos += 1
        if pos >= length:
            return None
        if s[pos] in '[]{}:,':  # Single character tokens
            pos += 1
            return s[pos - 1]
        start = pos

        if s[pos] == '"':
            while True:
                pos += 1
                if pos >= length:
                    raise ValueError("Unterminated string")
                if s[pos] == '"':
                    break
                if s[pos] == '\\':
                    pos += 1
            result = s[start:pos + 1]
            pos += 1
            return result

        if s[pos].isdigit() or (s[pos] == '-' and pos + 1 < length and s[pos + 1].isdigit()):
            while pos < length and (s[pos].isdigit() or s[pos] in '.-'):
                pos += 1
            return s[start:pos]

        if s.startswith('true', pos):
            pos += 4
            return True
        if s.startswith('false', pos):
            pos += 5
            return False
        if s.startswith('null', pos):
            pos += 4
            return None

        return None

    def parse_value():
        token = next_token()
        if isinstance(token, str) and token.startswith('"'):
            return token[1:-1].encode('utf-8').decode('unicode_escape')
        if token in {'true', 'false', 'null'}:
            return token
        if isinstance(token, bool):
            return token
        if token is None:
            return None
        if token.isdigit() or (token[0] == '-' and len(token) > 1):
            try:
                if '.' in token:
                    return float(token)
                return int(token)
            except ValueError:
                raise ValueError(f"Invalid number: {token}")
        if token == '[':
            return parse_array()
        if token == '{':
            return parse_object()

        raise ValueError(f"Unexpected token: {token}")

    def parse_array():
        array = []
        token = next_token()
        if token != '[':
            raise ValueError("Expected '['")
        while True:
            token = next_token()
            if token is None:
                raise ValueError("Unexpected end of JSON")
            if token == ']':
                break
            if token == ',':
                continue
            pos -= 1  # Unconsume the token
            array.append(parse_value())

        return array

    def parse_object():
        obj = {}
        token = next_token()
        if token != '{':
            raise ValueError("Expected '{'")
        while True:
            token = next_token()
            if token == '}':
                break
            if token == ',':
                continue
            if not isinstance(token, str) or not token.startswith('"'):
                raise ValueError("Expected key string in object")
            key = token[1:-1].encode('utf-8').decode('unicode_escape')
            token = next_token()
            if token != ':':
                raise ValueError("Expected ':' after key in object")
            obj[key] = parse_value()
        return obj

    return parse_value()

def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using an iterative parsing technique
    with state management via a stack. It handles strings with escapes, numbers,
    booleans, null, arrays, and objects.
    """

    class JSONParser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.length = len(s)
            self.stack = []
            self.current = None

        def parse(self):
            while self.pos < self.length:
                if self.s[self.pos].isspace():
                    self.pos += 1
                    continue

                char = self.s[self.pos]

                if char == '{':
                    self.stack.append({})
                    self.current = self.stack[-1]  # Current context is the object
                    self.pos += 1
                elif char == '}':
                    if len(self.stack) < 2:
                        raise ValueError("Unexpected '}'")
                    self.stack.pop()
                    self.current = self.stack[-1] if self.stack else None
                    self.pos += 1
                elif char == '[':
                    self.stack.append([])
                    self.current = self.stack[-1]  # Current context is the array
                    self.pos += 1
                elif char == ']':
                    if len(self.stack) < 2:
                        raise ValueError("Unexpected ']'")
                    self.stack.pop()
                    self.current = self.stack[-1] if self.stack else None
                    self.pos += 1
                elif char == '"':
                    self.current.append(self.parse_string())
                elif char.isdigit() or (char == '-' and self.s[self.pos + 1].isdigit()):
                    self.current.append(self.parse_number())
                elif self.s.startswith('true', self.pos):
                    self.current.append(True)
                    self.pos += 4
                elif self.s.startswith('false', self.pos):
                    self.current.append(False)
                    self.pos += 5
                elif self.s.startswith('null', self.pos):
                    self.current.append(None)
                    self.pos += 4
                elif char == ':':
                    self.pos += 1  # Skip colon
                elif char == ',':
                    self.pos += 1  # Skip comma
                else:
                    raise ValueError(f"Unexpected character: '{char}'")

            if len(self.stack) != 1:
                raise ValueError("Incomplete JSON structure")
            return self.stack.pop()

        def parse_string(self):
            start = self.pos + 1  # Skip opening quote
            self.pos += 1
            escaped = False
            while self.pos < self.length:
                char = self.s[self.pos]
                if char == '"' and not escaped:
                    result = self.s[start:self.pos]
                    self.pos += 1
                    return result
                escaped = (char == '\\') and not escaped
                self.pos += 1

            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.s[self.pos] == '-':
                self.pos += 1

            while self.pos < self.length and (self.s[self.pos].isdigit() or self.s[self.pos] == '.'):
                self.pos += 1

            number_str = self.s[start:self.pos]
            if '.' in number_str:
                return float(number_str)
            else:
                return int(number_str)

    parser = JSONParser(s)
    return parser.parse()

